-- Explicit SYNTHETIC-ONLY legacy UUID layout for browser QA. No customer data.
-- Not a live adapter, not an install-time seed, and not imported at normal startup.
CREATE TABLE leads(id TEXT PRIMARY KEY,external_id TEXT,full_name TEXT,first_name TEXT,last_name TEXT,primary_phone TEXT,phone_normalized TEXT,email TEXT,lead_source TEXT,original_creation_date TEXT,pipeline_stage TEXT,source_status TEXT,contact_status TEXT,assigned_manager TEXT,last_contact_at TEXT,next_followup_at TEXT,do_not_contact BOOLEAN,notes TEXT,origin TEXT,raw_payload TEXT,created_at TEXT,updated_at TEXT);
CREATE TABLE properties(id TEXT PRIMARY KEY,external_id TEXT,address_line1 TEXT,city TEXT,state TEXT,zip_code TEXT,property_type TEXT,bedrooms REAL,bathrooms REAL,square_footage REAL,year_built INTEGER,county TEXT,lot_acres REAL,asking_price REAL,estimated_value REAL,repair_estimate REAL,extra TEXT);
CREATE TABLE lead_properties(id TEXT PRIMARY KEY,lead_id TEXT,property_id TEXT,role TEXT,is_primary BOOLEAN);
CREATE TABLE activities(id TEXT PRIMARY KEY,lead_id TEXT,external_id TEXT,activity_type TEXT,direction TEXT,outcome TEXT,occurred_at TEXT,recorded_at TEXT,created_at TEXT,summary TEXT,detail TEXT,source TEXT,raw_payload TEXT);
CREATE TABLE followups(id TEXT PRIMARY KEY,lead_id TEXT,due_at TEXT,priority INTEGER,reason TEXT,suggested_next_action TEXT,status TEXT,completed_at TEXT,completion_outcome TEXT,creation_source TEXT,ai_suggested BOOLEAN,created_at TEXT);
CREATE TABLE message_drafts(id TEXT PRIMARY KEY,lead_id TEXT,body TEXT,edited_body TEXT,created_at TEXT);
CREATE TABLE call_plans(id TEXT PRIMARY KEY,lead_id TEXT,opener TEXT,questions TEXT,created_at TEXT);
